#!/bin/bash
set -e

# Medicine Type concept:
# - New master_drug_types + master_dosage_options tables (already
#   applied live, with 7 starter types and dosage phrasings, and 43
#   of your 54 existing drugs auto-mapped from their old free-text
#   'Form' field -- 11 left unassigned for manual review).
# - Financial Masters (Pharmacy tab): Type dropdown replaces free-text
#   Form input on drugs, new Type column in the table, and a 'Manage
#   Drug Types & Dosage Options' panel to add/rename types and their
#   dosage phrasings.
# - Doctor module Prescription: picking a drug from the Pharmacy master
#   now shows that drug's type-specific dosage options (e.g. 'Apply
#   thin layer' for an ointment) instead of the old fixed drop/tablet
#   list. Free-typed drug names or drugs still missing a Type fall
#   back to the original generic options, so nothing is ever empty.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/(main)/master-data"
echo "" | base64 -d > "app/(main)/master-data/actions.js"
echo "Wrote app/(main)/master-data/actions.js"

mkdir -p "app/(main)/master-data/financial"
echo "" | base64 -d > "app/(main)/master-data/financial/page.js"
echo "Wrote app/(main)/master-data/financial/page.js"

mkdir -p "app/consultation/[id]"
echo "" | base64 -d > "app/consultation/[id]/consultation-form.js"
echo "Wrote app/consultation/[id]/consultation-form.js"

git add "app/(main)/master-data/actions.js" "app/(main)/master-data/financial/page.js" "app/consultation/[id]/consultation-form.js"
git commit -m "Add medicine Type concept: Financial Masters type management + type-aware doctor Prescription dosage"
git push

echo "Done."
